package br.com.fiap.bank.plataforma.application;
import br.com.fiap.bank.plataforma.domain.*; import br.com.fiap.bank.plataforma.application.dto.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.*;
@Service @Transactional public class CreditoApplicationService {
 private final SolicitacaoCreditoRepository repo; private final ScrGateway scr; private final BureauGateway bureau; private final NotificacaoGateway notificacao; private final CoreBancarioGateway core;
 public CreditoApplicationService(SolicitacaoCreditoRepository r,ScrGateway s,BureauGateway b,NotificacaoGateway n,CoreBancarioGateway c){repo=r;scr=s;bureau=b;notificacao=n;core=c;}
 private String cpf(String x){return x.replaceAll("\\D","");} private SolicitacaoCredito require(Long id){return repo.findById(id).orElseThrow(()->new RecursoNaoEncontradoException("Solicitação não encontrada: "+id));}
 public SolicitacaoCreditoResponseDTO solicitar(SolicitarCreditoRequest r){String cpf=cpf(r.cpfCliente());boolean restricao=scr.possuiRestricao(cpf);int score=bureau.consultarScore(cpf);core.consultarContaCliente(cpf);StatusSolicitacao status;String parecer;
 if(restricao){status=StatusSolicitacao.REPROVADO;parecer="Solicitação reprovada automaticamente por restrições no SCR.";}else if(score<500){status=StatusSolicitacao.REPROVADO;parecer="Solicitação reprovada automaticamente por score insuficiente ("+score+").";}else{BigDecimal parcela=r.valorSolicitado().divide(BigDecimal.valueOf(r.quantidadeParcelas()),2,RoundingMode.HALF_UP);if(parcela.compareTo(r.rendaMensal().multiply(new BigDecimal("0.30")))>0){status=StatusSolicitacao.EM_ANALISE;parecer="Encaminhada para análise da Mesa de Operações: parcela estimada compromete mais de 30% da renda.";}else{status=StatusSolicitacao.APROVADO;parecer="Solicitação aprovada automaticamente pelo motor de crédito.";}}
 var x=new SolicitacaoCredito(null,cpf,r.nomeCliente(),r.tipoCredito(),r.valorSolicitado(),r.quantidadeParcelas(),r.rendaMensal(),score,status,parecer,restricao,score,LocalDateTime.now(),LocalDateTime.now());var saved=repo.save(x);notificacao.enviar(cpf,"Sua solicitação de crédito #"+saved.getId()+" está no status: "+status);return SolicitacaoCreditoResponseDTO.from(saved);}
 @Transactional(readOnly=true) public List<SolicitacaoCreditoResponseDTO> listar(){return repo.findAll().stream().map(SolicitacaoCreditoResponseDTO::from).toList();}
 @Transactional(readOnly=true) public List<SolicitacaoCreditoResponseDTO> listarPorCpf(String c){return repo.findByCpf(cpf(c)).stream().map(SolicitacaoCreditoResponseDTO::from).toList();}
 @Transactional(readOnly=true) public SolicitacaoCreditoResponseDTO buscar(Long id){return SolicitacaoCreditoResponseDTO.from(require(id));}
 public SolicitacaoCreditoResponseDTO decidir(Long id,String decisao,String parecer){var x=require(id);StatusSolicitacao s;try{s=StatusSolicitacao.valueOf(decisao.toUpperCase(Locale.ROOT));}catch(Exception e){throw new IllegalArgumentException("Decisão deve ser APROVADO ou REPROVADO.");}if(s==StatusSolicitacao.EM_ANALISE)throw new IllegalArgumentException("Decisão deve ser APROVADO ou REPROVADO.");x.decidir(s,parecer==null||parecer.isBlank()?"Decisão registrada pela Mesa de Operações.":parecer);var saved=repo.save(x);notificacao.enviar(saved.getCpfCliente(),"Sua solicitação #"+saved.getId()+" foi "+s+" pela Mesa de Operações.");return SolicitacaoCreditoResponseDTO.from(saved);}
 public Map<String,Object> consultarConta(String c){return core.consultarContaCliente(cpf(c));}
}
